package android.opengl;public class GLES30 extends GLES20{public static final int GL_SYNC_GPU_COMMANDS_COMPLETE=0x9117,GL_ALREADY_SIGNALED=0x911a,GL_TIMEOUT_EXPIRED=0x911b,GL_CONDITION_SATISFIED=0x911c,GL_WAIT_FAILED=0x911d,GL_SYNC_FLUSH_COMMANDS_BIT=1;public static final long GL_TIMEOUT_IGNORED=-1L;public static long glFenceSync(int c,int f){return FakeGpu.fence();}public static int glClientWaitSync(long s,int flags,long t){return FakeGpu.poll(s);}public static void glWaitSync(long s,int f,long t){FakeGpu.serverWait(s);}public static void glDeleteSync(long s){FakeGpu.fences.remove(s);}}
